CREATE TABLE IF NOT EXISTS p13_union_fight_car_impacts (
 id CHAR(64) PRIMARY KEY,match_id CHAR(64) NOT NULL,car_guid BIGINT NOT NULL,ordinal BIGINT NOT NULL,factory_guid BIGINT NOT NULL,factory_id BIGINT NOT NULL,generation BIGINT NOT NULL,born_at BIGINT NOT NULL,car_camp BIGINT NOT NULL,factory_source_hash CHAR(64) NOT NULL,generation_source_hash CHAR(64) NOT NULL,identity_hash CHAR(64) NOT NULL,player_id BIGINT NOT NULL,camp BIGINT NOT NULL,item_id VARCHAR(64) NOT NULL,stamp BIGINT NOT NULL,offer_hash CHAR(64) NOT NULL,hp_percent BIGINT NOT NULL,inventory_before BIGINT NOT NULL,inventory_after BIGINT NOT NULL,logical_at BIGINT NOT NULL,applied_at BIGINT NOT NULL,hp_before DOUBLE NOT NULL,hp_after DOUBLE NOT NULL,`before` BLOB NOT NULL,`after` BLOB NOT NULL,before_hash CHAR(64) NOT NULL,after_hash CHAR(64) NOT NULL,source_hash CHAR(64) NOT NULL,UNIQUE KEY p13_car_impact_seq(match_id,car_guid,ordinal),KEY p13_car_impact_owner(match_id,player_id,stamp)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
